+:root{
+  --bg:#000;
+  --bg2:#141414;
+  --panel:#0f0f0f;
+  --panel2:#111;
+  --text:#fff;
+  --muted:rgba(255,255,255,.72);
+  --muted2:rgba(255,255,255,.55);
+  --line:rgba(255,255,255,.12);
+  --red:#E50914;
+  --red2:#ff2a2a;
+  --shadow:0 18px 60px rgba(0,0,0,.6);
+  --radius:18px;
+  --radius-sm:12px;
+  --max:1120px;
+  --focus:0 0 0 4px rgba(229,9,20,.28);
+}
+
+*{box-sizing:border-box}
+html,body{height:100%}
+body{
+  margin:0;
+  background:radial-gradient(1200px 600px at 12% -10%, rgba(229,9,20,.20), transparent 60%),
+             radial-gradient(900px 600px at 90% 0%, rgba(255,255,255,.10), transparent 55%),
+             linear-gradient(180deg, var(--bg), var(--bg2));
+  color:var(--text);
+  font-family:ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji","Segoe UI Emoji";
+  -webkit-font-smoothing:antialiased;
+  text-rendering:optimizeLegibility;
+}
+
+a{color:inherit; text-decoration:none}
+button,input,select{font:inherit}
+
+.container{max-width:var(--max); margin:0 auto; padding:0 20px}
+
+.skip{
+  position:absolute; left:-999px; top:auto; width:1px; height:1px; overflow:hidden;
+}
+.skip:focus{left:16px; top:16px; width:auto; height:auto; padding:12px 14px; border-radius:12px; background:#0b0b0b; box-shadow:var(--shadow)}
+
+/* Header */
+.header{
+  position:sticky;
+  top:0;
+  z-index:20;
+  backdrop-filter:saturate(120%) blur(10px);
+  background:linear-gradient(180deg, rgba(0,0,0,.82), rgba(0,0,0,.55));
+  border-bottom:1px solid rgba(255,255,255,.06);
+}
+.header-inner{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  min-height:76px;
+  gap:14px;
+}
+.brand{
+  display:flex;
+  align-items:center;
+  gap:10px;
+  font-weight:900;
+  letter-spacing:.6px;
+  text-transform:uppercase;
+}
+.brand-mark{
+  width:34px; height:34px;
+  border-radius:10px;
+  background:linear-gradient(145deg, var(--red), #b3050c);
+  box-shadow:0 10px 30px rgba(229,9,20,.25);
+  position:relative;
+}
+.brand-mark:after{
+  content:"";
+  position:absolute; inset:8px 10px;
+  border-left:10px solid rgba(255,255,255,.92);
+  border-top:6px solid transparent;
+  border-bottom:6px solid transparent;
+  transform:skewX(-8deg);
+}
+.nav-actions{display:flex; align-items:center; gap:10px}
+.lang{
+  height:40px;
+  padding:0 12px;
+  border-radius:999px;
+  background:rgba(0,0,0,.35);
+  color:var(--text);
+  border:1px solid rgba(255,255,255,.18);
+}
+
+.btn{
+  display:inline-flex;
+  align-items:center;
+  justify-content:center;
+  gap:10px;
+  height:44px;
+  padding:0 16px;
+  border-radius:999px;
+  border:1px solid rgba(255,255,255,.18);
+  background:rgba(255,255,255,.06);
+  color:var(--text);
+  cursor:pointer;
+  transition:transform .12s ease, background .12s ease, border-color .12s ease;
+}
+.btn:hover{transform:translateY(-1px); background:rgba(255,255,255,.10); border-color:rgba(255,255,255,.26)}
+.btn:active{transform:translateY(0)}
+.btn:focus-visible{outline:none; box-shadow:var(--focus)}
+.btn-primary{
+  border-color:rgba(229,9,20,.9);
+  background:linear-gradient(180deg, var(--red), #b9050d);
+}
+.btn-primary:hover{background:linear-gradient(180deg, var(--red2), #cc060f)}
+
+/* Hero */
+.hero{
+  position:relative;
+  overflow:hidden;
+}
+.hero:before{
+  content:"";
+  position:absolute; inset:-20px;
+  background:
+    radial-gradient(900px 520px at 20% 30%, rgba(229,9,20,.28), transparent 60%),
+    radial-gradient(820px 540px at 85% 10%, rgba(255,255,255,.12), transparent 60%),
+    linear-gradient(180deg, rgba(0,0,0,.2), rgba(0,0,0,.94));
+  pointer-events:none;
+  z-index:1;
+}
+.hero:after{
+  content:"";
+  position:absolute;
+  inset:-120px;
+  background-image:var(--poster-mosaic);
+  background-size:cover;
+  background-position:center;
+  filter:saturate(1.1) contrast(1.05);
+  transform:rotate(-6deg) scale(1.12);
+  opacity:.92;
+  z-index:0;
+}
+.hero-inner{
+  position:relative;
+  z-index:2;
+  padding:92px 0 72px;
+}
+.hero-grid{display:grid; grid-template-columns:1.1fr .9fr; gap:28px; align-items:center}
+.kicker{
+  display:inline-flex;
+  align-items:center;
+  gap:10px;
+  padding:8px 12px;
+  border-radius:999px;
+  background:rgba(0,0,0,.5);
+  border:1px solid rgba(255,255,255,.16);
+  color:rgba(255,255,255,.85);
+  font-weight:700;
+  letter-spacing:.3px;
+}
+.kicker-dot{width:8px; height:8px; border-radius:99px; background:var(--red); box-shadow:0 0 0 6px rgba(229,9,20,.18)}
+.h1{
+  margin:14px 0 8px;
+  font-size:clamp(40px, 4.5vw, 64px);
+  line-height:1.02;
+  letter-spacing:-.02em;
+  font-weight:900;
+}
+.sub{
+  margin:0 0 18px;
+  font-size:clamp(16px, 1.6vw, 20px);
+  color:rgba(255,255,255,.86);
+}
+.prompt{margin:0 0 14px; color:var(--muted); font-size:16px; max-width:56ch}
+
+.signup{
+  display:flex;
+  gap:10px;
+  align-items:stretch;
+  background:rgba(0,0,0,.55);
+  border:1px solid rgba(255,255,255,.18);
+  border-radius:999px;
+  padding:8px;
+  box-shadow:var(--shadow);
+}
+.signup input{
+  flex:1;
+  min-width:0;
+  border:none;
+  background:transparent;
+  color:var(--text);
+  padding:10px 12px 10px 14px;
+  outline:none;
+  font-weight:600;
+}
+.signup input::placeholder{color:rgba(255,255,255,.55)}
+.signup input:focus-visible{box-shadow:none}
+
+.trust{
+  margin-top:14px;
+  display:flex;
+  flex-wrap:wrap;
+  gap:10px;
+  color:rgba(255,255,255,.72);
+  font-size:14px;
+}
+.pill{
+  display:inline-flex;
+  align-items:center;
+  gap:8px;
+  padding:8px 10px;
+  border-radius:999px;
+  background:rgba(255,255,255,.06);
+  border:1px solid rgba(255,255,255,.12);
+}
+.pill svg{width:16px; height:16px; opacity:.95}
+
+.hero-card{
+  border-radius:var(--radius);
+  background:linear-gradient(180deg, rgba(15,15,15,.86), rgba(10,10,10,.68));
+  border:1px solid rgba(255,255,255,.12);
+  padding:18px;
+  box-shadow:var(--shadow);
+}
+.preview-title{margin:0 0 12px; font-weight:900; letter-spacing:.2px}
+.preview-grid{display:grid; grid-template-columns:repeat(3, 1fr); gap:10px}
+.mini-poster{
+  aspect-ratio:2/3;
+  border-radius:14px;
+  background:
+    radial-gradient(140px 80px at 30% 20%, rgba(255,255,255,.16), transparent 60%),
+    linear-gradient(145deg, rgba(229,9,20,.55), rgba(0,0,0,.35));
+  border:1px solid rgba(255,255,255,.10);
+  position:relative;
+  overflow:hidden;
+}
+.mini-poster:after{
+  content:"";
+  position:absolute; inset:0;
+  background:linear-gradient(180deg, transparent, rgba(0,0,0,.78));
+}
+.mini-poster span{
+  position:absolute; left:10px; bottom:10px; right:10px;
+  z-index:2;
+  font-weight:800;
+  font-size:12px;
+  letter-spacing:.2px;
+}
+.mini-badge{
+  position:absolute; top:10px; left:10px;
+  z-index:2;
+  padding:6px 8px;
+  border-radius:999px;
+  background:rgba(0,0,0,.55);
+  border:1px solid rgba(255,255,255,.14);
+  font-weight:800;
+  font-size:12px;
+}
+
+/* Sections */
+section{padding:56px 0}
+.section-title{
+  font-size:28px;
+  margin:0 0 16px;
+  font-weight:900;
+  letter-spacing:-.01em;
+}
+
+/* Trending carousel */
+.carousel-wrap{
+  position:relative;
+  border-radius:var(--radius);
+  background:linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02));
+  border:1px solid rgba(255,255,255,.10);
+  padding:16px 12px 14px;
+}
+.carousel{
+  display:flex;
+  gap:14px;
+  overflow:auto;
+  padding:6px 6px 10px;
+  scroll-snap-type:x mandatory;
+  -webkit-overflow-scrolling:touch;
+}
+.carousel::-webkit-scrollbar{height:10px}
+.carousel::-webkit-scrollbar-thumb{background:rgba(255,255,255,.18); border-radius:999px}
+.carousel::-webkit-scrollbar-track{background:rgba(255,255,255,.06); border-radius:999px}
+
+.trend-card{
+  flex:0 0 auto;
+  width:clamp(178px, 18vw, 240px);
+  scroll-snap-align:start;
+  position:relative;
+  border-radius:18px;
+  overflow:hidden;
+  border:1px solid rgba(255,255,255,.12);
+  background:#101010;
+  box-shadow:0 14px 34px rgba(0,0,0,.45);
+}
+.trend-poster{
+  aspect-ratio:2/3;
+  background:var(--poster);
+  background-size:cover;
+  background-position:center;
+  filter:saturate(1.1) contrast(1.05);
+}
+.trend-overlay{
+  position:absolute; inset:0;
+  background:linear-gradient(180deg, rgba(0,0,0,.12), rgba(0,0,0,.86));
+}
+.trend-rank{
+  position:absolute;
+  left:-8px;
+  bottom:-12px;
+  font-size:92px;
+  font-weight:1000;
+  letter-spacing:-.06em;
+  color:rgba(255,255,255,.14);
+  text-shadow:0 14px 40px rgba(0,0,0,.7);
+  z-index:2;
+}
+.trend-meta{
+  position:absolute;
+  left:14px;
+  right:14px;
+  bottom:14px;
+  z-index:3;
+}
+.trend-title{
+  margin:0;
+  font-weight:900;
+  font-size:16px;
+}
+.trend-tag{
+  margin-top:6px;
+  display:inline-flex;
+  gap:8px;
+  align-items:center;
+  font-size:12px;
+  color:rgba(255,255,255,.78);
+}
+.tag{
+  padding:6px 8px;
+  border-radius:999px;
+  border:1px solid rgba(255,255,255,.14);
+  background:rgba(0,0,0,.42);
+}
+
+.car-controls{position:absolute; top:14px; right:12px; display:flex; gap:10px}
+.icon-btn{
+  width:42px; height:42px;
+  border-radius:999px;
+  border:1px solid rgba(255,255,255,.16);
+  background:rgba(0,0,0,.35);
+  color:var(--text);
+  display:grid;
+  place-items:center;
+  cursor:pointer;
+  transition:transform .12s ease, background .12s ease;
+}
+.icon-btn:hover{transform:translateY(-1px); background:rgba(0,0,0,.5)}
+.icon-btn:focus-visible{outline:none; box-shadow:var(--focus)}
+.icon-btn svg{width:18px; height:18px}
+
+/* Features */
+.feature-grid{display:grid; grid-template-columns:repeat(4, 1fr); gap:14px}
+.feature{
+  border-radius:var(--radius);
+  border:1px solid rgba(255,255,255,.10);
+  background:linear-gradient(180deg, rgba(255,255,255,.05), rgba(255,255,255,.02));
+  padding:18px;
+  min-height:160px;
+  position:relative;
+  overflow:hidden;
+}
+.feature:before{
+  content:"";
+  position:absolute; inset:-40px;
+  background:radial-gradient(260px 200px at 25% 20%, rgba(229,9,20,.18), transparent 60%);
+  pointer-events:none;
+}
+.feature h3{margin:0 0 8px; font-size:18px; font-weight:900; position:relative}
+.feature p{margin:0; color:var(--muted); line-height:1.45; position:relative}
+.feature .f-icon{
+  position:absolute;
+  right:14px;
+  bottom:14px;
+  width:44px; height:44px;
+  border-radius:14px;
+  background:rgba(0,0,0,.45);
+  border:1px solid rgba(255,255,255,.12);
+  display:grid;
+  place-items:center;
+}
+.feature .f-icon svg{width:22px; height:22px; opacity:.95}
+
+/* FAQ */
+.faq{
+  border-radius:var(--radius);
+  border:1px solid rgba(255,255,255,.10);
+  background:linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02));
+  overflow:hidden;
+}
+.faq-item{border-top:1px solid rgba(255,255,255,.10)}
+.faq-item:first-child{border-top:none}
+.faq-q{
+  width:100%;
+  text-align:left;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:14px;
+  padding:18px 18px;
+  background:transparent;
+  border:none;
+  color:var(--text);
+  cursor:pointer;
+  font-weight:900;
+  font-size:18px;
+}
+.faq-q:focus-visible{outline:none; box-shadow:var(--focus)}
+.faq-q .plus{
+  width:36px; height:36px;
+  border-radius:999px;
+  background:rgba(0,0,0,.38);
+  border:1px solid rgba(255,255,255,.14);
+  display:grid;
+  place-items:center;
+  flex:0 0 auto;
+}
+.faq-q svg{width:18px; height:18px; transition:transform .22s ease}
+.faq-item[aria-expanded="true"] .faq-q svg{transform:rotate(45deg)}
+.faq-a{
+  max-height:0;
+  overflow:hidden;
+  transition:max-height .28s ease;
+}
+.faq-a-inner{padding:0 18px 18px; color:var(--muted); line-height:1.55}
+
+/* Bottom CTA */
+.cta{
+  border-radius:var(--radius);
+  border:1px solid rgba(255,255,255,.10);
+  background:
+    radial-gradient(720px 280px at 20% 20%, rgba(229,9,20,.20), transparent 60%),
+    linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02));
+  padding:28px;
+  box-shadow:var(--shadow);
+}
+.cta .prompt{margin:0 0 14px}
+
+/* Login */
+.auth-shell{min-height:calc(100vh - 76px); display:grid; place-items:center; padding:56px 0}
+.auth-card{
+  width:min(520px, 100%);
+  border-radius:var(--radius);
+  border:1px solid rgba(255,255,255,.12);
+  background:linear-gradient(180deg, rgba(0,0,0,.72), rgba(10,10,10,.52));
+  box-shadow:var(--shadow);
+  padding:22px;
+}
+.auth-card h1{margin:0 0 8px; font-size:26px; font-weight:1000; letter-spacing:-.01em}
+.auth-card .muted{margin:0 0 18px; color:var(--muted)}
+.field{display:flex; flex-direction:column; gap:8px; margin-bottom:12px}
+.label{font-weight:800; color:rgba(255,255,255,.86)}
+.input{
+  height:48px;
+  border-radius:14px;
+  border:1px solid rgba(255,255,255,.16);
+  background:rgba(255,255,255,.06);
+  color:var(--text);
+  padding:0 14px;
+  outline:none;
+}
+.input:focus{box-shadow:var(--focus); border-color:rgba(229,9,20,.75)}
+.error{color:#ffb4b4; font-size:13px; margin-top:4px; display:none}
+.error.show{display:block}
+
+.help-toggle{
+  margin-top:14px;
+  background:transparent;
+  border:none;
+  color:rgba(255,255,255,.88);
+  font-weight:900;
+  cursor:pointer;
+  display:inline-flex;
+  gap:10px;
+  align-items:center;
+}
+.help-toggle:focus-visible{outline:none; box-shadow:var(--focus); border-radius:12px}
+.help-panel{
+  margin-top:10px;
+  border-radius:16px;
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(0,0,0,.35);
+  max-height:0;
+  overflow:hidden;
+  transition:max-height .26s ease;
+}
+.help-inner{padding:12px 14px; color:var(--muted); line-height:1.5}
+.help-links{margin:10px 0 0; padding-left:18px}
+.help-links li{margin:6px 0}
+
+/* Footer */
+.footer{
+  padding:44px 0 52px;
+  border-top:1px solid rgba(255,255,255,.08);
+  background:linear-gradient(180deg, rgba(0,0,0,.2), rgba(0,0,0,.65));
+}
+.footer .contact{color:rgba(255,255,255,.78); margin:0 0 16px}
+.footer-grid{display:grid; grid-template-columns:repeat(4, 1fr); gap:10px 18px}
+.footer a{
+  color:rgba(255,255,255,.70);
+  text-decoration:underline;
+  text-decoration-color:rgba(255,255,255,.22);
+  text-underline-offset:3px;
+}
+.footer a:hover{color:rgba(255,255,255,.92)}
+.footer-bottom{margin-top:18px; display:flex; flex-wrap:wrap; gap:12px; align-items:center; justify-content:space-between}
+.legal{color:rgba(255,255,255,.52); font-size:13px; max-width:80ch}
+
+/* Responsive */
+@media (max-width: 980px){
+  .hero-grid{grid-template-columns:1fr; gap:18px}
+  .hero-inner{padding:72px 0 54px}
+  .feature-grid{grid-template-columns:repeat(2, 1fr)}
+  section{padding:46px 0}
+}
+@media (max-width: 560px){
+  .signup{flex-direction:column; border-radius:18px}
+  .btn{height:46px}
+  .lang{display:none}
+  .feature-grid{grid-template-columns:1fr}
+  .footer-grid{grid-template-columns:repeat(2, 1fr)}
+  .car-controls{top:12px}
+}
+
+@media (prefers-reduced-motion: reduce){
+  *{scroll-behavior:auto !important}
+  .faq-a, .help-panel, .icon-btn, .btn{transition:none !important}
+}
+
*** End Patch
PATCH

